<script setup lang="ts">
import{computed,ref}from'vue';import{useI18n}from'vue-i18n';import{getTool}from'../registry';import{formatJwtInspection,inspectJwt}from'./jwt'
const{t}=useI18n();const tool=getTool('soc-tools.jwt');const input=ref('');const output=ref('');const error=ref('');const copied=ref(false);const inputBytes=computed(()=>new TextEncoder().encode(input.value).byteLength);const isOverLimit=computed(()=>inputBytes.value>tool.recommendedMaxInputBytes);function transform(){error.value='';copied.value=false;if(!input.value){output.value='';return}try{output.value=formatJwtInspection(inspectJwt(input.value))}catch{output.value='';error.value=t('tools.jwt.invalid')}}function clear(){input.value='';output.value='';error.value='';copied.value=false}async function copyOutput(){if(output.value){await navigator.clipboard.writeText(output.value);copied.value=true}}
</script>
<template><section class="tool-page" aria-labelledby="tool-title"><header class="tool-heading"><span class="category">{{ t(`categories.${tool.category}`) }}</span><h1 id="tool-title">{{ t(tool.nameKey) }}</h1><p>{{ t(tool.descriptionKey) }}</p></header><div class="io-panel"><div class="terminal-titlebar"><span class="window-marks" aria-hidden="true"><i /><i /><i /></span><span>[ jwt ]</span></div><div class="io-strip"><span class="byte-count">{{ inputBytes }} B</span><div class="strip-actions"><button class="icon-button" type="button" :disabled="!output" :aria-label="copied?t('common.copied'):t('common.copy')" @click="copyOutput"><svg aria-hidden="true" viewBox="0 0 24 24"><rect x="9" y="9" width="11" height="11" rx="2" /><path d="M15 9V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v7a2 2 0 0 0 2 2h3" /></svg></button><button class="icon-button" type="button" :aria-label="t('common.clear')" @click="clear"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M3 6h18M8 6V4h8v2m-9 0 1 14h8l1-14" /></svg></button></div></div><p class="notice warning" role="note">{{ t('tools.jwt.limitation') }}</p><p v-if="isOverLimit" class="notice warning" role="status">{{ t('common.warning',{size:'256 KB'}) }}</p><div class="editor-grid"><div class="field"><label for="jwt-input"><span>$</span> {{ t('common.input') }}</label><div class="terminal-editor input-editor"><span class="editor-prompt" aria-hidden="true">$</span><textarea id="jwt-input" v-model="input" :class="{invalid:error}" :aria-invalid="Boolean(error)" :aria-describedby="error?'jwt-error':undefined" :placeholder="t('tools.jwt.placeholder')" spellcheck="false" @input="transform" /></div></div><div class="field"><label for="jwt-output"><span>&gt;</span> {{ t('common.output') }}</label><div class="terminal-editor"><span class="editor-prompt" aria-hidden="true">&gt;</span><textarea id="jwt-output" :value="output" :placeholder="t('common.result')" readonly /></div></div></div><p v-if="error" id="jwt-error" class="notice error" role="alert">{{ error }}</p></div></section></template>
